  "tool": {
    "tool": "GetMcpServerStatus",
    "description": "The runtime status of the user's installed MCP servers (connected / needsAuth / error, per account). Pass server_id (the server identifier, NEVER a display name) for one server; omit it to list everything. Use this to see which connectors still need authentication, to find the identifier a lifecycle tool needs — the same one GetDynamicTools and CallDynamicTool address — or to check a connector after installing or authenticating. Read-only and never needs the user's permission.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "server_id": {
          "type": "string",
          "description": "Optional. One server to report on. The server identifier shown by GetMcpServerStatus — the same identifier GetDynamicTools and CallDynamicTool address, e.g. \"dashboard-team-1-Slack\". Never a display name. Omit to list every installed server."
        }
      }
    }
  }
}

